// studio_final.ino — ESP32-S3
// GPIO4: бродкаст "MATRIX" (все ПК с сервером запускают матрицу + отвечают IAM)
// BOOT:  TCP "OFF" всем запомненным ПК во всех трёх сетях
// Ни одного delay(): всё на millis() и состояниях
#include <WiFi.h>
#include <WiFiUdp.h>
#include <EEPROM.h>

// ===== Сети студии =====
const char* SSIDS[]  = { "DIR-615T-0DBC", "KIBERone", "KIBERone5" };
const char* PASSES[] = { "23233010", "KIBERone", "KIBERone" };
const int NET_COUNT = 3;

// ===== Порты и пины =====
const int TCP_PORT = 8085;   // приём OFF на ПК
const int UDP_PORT = 8086;   // матрица / скан
const int BTN_MATRIX = 4;    // GPIO4 — матрица
const int BTN_OFF    = 0;    // BOOT — выключение

// ===== Настройки =====
const int MAX_PCS     = 20;
const int TCP_TIMEOUT = 150;          // мс на попытку TCP к одному ПК
const int EEPROM_SIZE = 512;
const unsigned long WIFI_TIMEOUT = 15000;
const unsigned long LISTEN_MS    = 2000;   // сколько слушать ответы IAM
const unsigned long BCAST_EVERY  = 400;    // интервал повторных бродкастов

// ===== Состояния =====
enum State { CONNECTING, ONLINE, LISTENING, OFFING };
State st = CONNECTING, resumeTo = ONLINE;

int curNet = 0;                 // к какой сети подключаемся сейчас
int offNet = 0, offIdx = 0;     // прогресс выключения
unsigned long stateT0 = 0, lastBcast = 0, listenUntil = 0;

WiFiUDP udp;
String ips[MAX_PCS];
int ipCount = 0;

// ===== Кнопки: дребезг на millis(), без delay =====
struct Btn {
  uint8_t pin;
  bool lastReading = false, state = false;
  unsigned long lastChange = 0;
};
Btn btnMatrix{BTN_MATRIX}, btnOff{BTN_OFF};

bool checkPress(Btn &b) {
  bool reading = (digitalRead(b.pin) == LOW);
  if (reading != b.lastReading) { b.lastChange = millis(); b.lastReading = reading; }
  if (millis() - b.lastChange > 50 && reading != b.state) {
    b.state = reading;
    if (b.state) return true;
  }
  return false;
}

// ===== Wi-Fi: подключение как состояние =====
void startConnect(int net, State after) {
  curNet = net;
  resumeTo = after;
  WiFi.mode(WIFI_STA);
  WiFi.disconnect(false);
  WiFi.begin(SSIDS[net], PASSES[net]);
  st = CONNECTING;
  stateT0 = millis();
}

void wifiTick() {
  if (st == CONNECTING) {
    if (WiFi.status() == WL_CONNECTED) {
      st = resumeTo;
    } else if (millis() - stateT0 > WIFI_TIMEOUT) {
      startConnect((curNet + 1) % NET_COUNT, resumeTo); // не дождались — следующая сеть
    }
  } else if (WiFi.status() != WL_CONNECTED) {
    startConnect(0, st == OFFING ? OFFING : ONLINE);    // отвалились — вернуться и продолжить
  }
}

// ===== EEPROM: список IP переживает выключение питания =====
void saveIps() {
  EEPROM.begin(EEPROM_SIZE);
  EEPROM.write(0, ipCount);
  int a = 1;
  for (int i = 0; i < ipCount; i++) {
    for (unsigned int c = 0; c < ips[i].length(); c++) EEPROM.write(a++, ips[i][c]);
    EEPROM.write(a++, '\n');
  }
  EEPROM.commit(); // без этого ничего не сохранится
}

void loadIps() {
  ipCount = 0;
  EEPROM.begin(EEPROM_SIZE);
  int n = (int)EEPROM.read(0);
  if (n > MAX_PCS) n = MAX_PCS;
  int a = 1;
  for (int i = 0; i < n; i++) {
    String cur = "";
    while (true) {
      char c = EEPROM.read(a++);
      if (c == '\n' || c == 0 || c == 255) break; // 255 = чистая флешка
      cur += c;
    }
    if (cur.length()) ips[ipCount++] = cur;
  }
}

void rememberIp(const String& ip) {
  for (int i = 0; i < ipCount; i++) if (ips[i] == ip) return;
  if (ipCount < MAX_PCS) ips[ipCount++] = ip;
}

// ===== Матрица: бродкаст в текущей сети + сбор ответов =====
void broadcastMatrix() {
  udp.beginPacket(IPAddress(255, 255, 255, 255), UDP_PORT);
  udp.print("MATRIX");
  udp.endPacket();
}

void startMatrix() {
  udp.begin(UDP_PORT);
  broadcastMatrix();
  lastBcast = millis();
  listenUntil = millis() + LISTEN_MS;
  st = LISTENING;
}

void listenTick() {
  if (millis() - lastBcast > BCAST_EVERY) { broadcastMatrix(); lastBcast = millis(); }
  int len = udp.parsePacket();
  if (len > 0) {
    char buf[64];
    if (len > 63) len = 63;
    int n = udp.read(buf, len);
    buf[n] = '\0';
    if (String(buf).startsWith("IAM:")) rememberIp(udp.remoteIP().toString());
  }
  if (millis() > listenUntil) { udp.stop(); saveIps(); st = ONLINE; }
}

// ===== Выключение: по TCP каждому запомненному ПК, во всех сетях =====
void offTick() {
  if (offNet >= NET_COUNT) { startConnect(0, ONLINE); return; }       // все сети пройдены
  if (curNet != offNet || WiFi.status() != WL_CONNECTED) {
    startConnect(offNet, OFFING);                                     // переключиться на сеть
    return;
  }
  if (offIdx < ipCount) {
    WiFiClient c;                                                     // одна попытка за проход
    if (c.connect(ips[offIdx].c_str(), TCP_PORT, TCP_TIMEOUT)) {
      c.print("OFF\n");
      c.stop();
    }
    offIdx++;
  } else { offNet++; offIdx = 0; }
}

void setup() {
  pinMode(BTN_MATRIX, INPUT_PULLUP);
  pinMode(BTN_OFF, INPUT_PULLUP);
  loadIps();
  startConnect(0, ONLINE);
}

void loop() {
  wifiTick();
  if (st == LISTENING) listenTick();
  if (st == OFFING)    offTick();

  if (st == ONLINE) {
    if (checkPress(btnMatrix)) startMatrix();                          // GPIO4: матрица
    if (checkPress(btnOff))    { offNet = 0; offIdx = 0; st = OFFING; } // BOOT: вырубить
  }
}
